#!/usr/bin/env bash

DIR=$(cd $(dirname $0) && pwd)

# Plan and submit the workflow generated by workflow_generator.py — the same
# command the generator prints. The transformation and replica catalogs are
# embedded in the workflow file; the site comes from a hosted site catalog
# (-s at generation time, or ~/.pegasusrc). SITE=condorpool plans on a plain
# HTCondor pool with no site catalog (generate with -e condorpool too).
WORKFLOW=${1:-$DIR/workflow.yml}
SITE=${SITE:-compute}

if [ ! -f "$WORKFLOW" ]; then
    echo "Usage: [SITE=condorpool] $0 [WORKFLOW.yml]"
    echo "No workflow file at $WORKFLOW — run the generator first, e.g.:"
    echo "  ./workflow_generator.py -f MERGE_DARTS_201903250500.nc"
    exit 1
fi

pegasus-plan \
    --conf $DIR/pegasus.properties \
    --dir $DIR/submit \
    -s $SITE \
    -o local \
    --submit \
    $WORKFLOW
